pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address[] calldata tos, uint256 v) public {
        vm.assume(tos.length > 0);
        Recorder rec = new Recorder();
        c.transfer(from, address(rec), tos, v);
        assertTrue(rec.count() == tos.length);
    }
}

contract Recorder {
    uint256 public count;

    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}
